// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Reentrance c;

    function setUp() public {
        c = new Reentrance();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint256 beforeRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { beforeRecorded = __r; } catch { return; }
        uint beforeContractBal = address(c).balance;
        try c.addToBalance{value: amount}() {} catch { return; }
        uint256 afterRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { afterRecorded = __r; } catch { return; }
        uint afterContractBal = address(c).balance;
        bool didRevert;
        try c.withdrawBalance() {
            didRevert = false;
        } catch {
            didRevert = true;
        }
        uint256 finalRecorded;
        try c.getBalance(address(this)) returns (uint256 __r) { finalRecorded = __r; } catch { return; }
        uint finalContractBal = address(c).balance;
        uint deltaRecorded = afterRecorded >= beforeRecorded ? afterRecorded - beforeRecorded : 0;
        assertTrue((!didRevert && finalRecorded == 0 && finalContractBal + deltaRecorded == afterContractBal) || (didRevert && finalRecorded == afterRecorded));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable { }
}
